import Link from "next/link";
import { UserPlusIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
} from "@/components/ui/card";
import { cn } from "@/lib/utils";

export type InstitutionSkillCardProps = {
  competitionId: string;
  skillId: string;
  skillName: string;
  familyName?: string | null;
  number?: string | null;
  quota?: {
    max: number;
    used: number;
    remaining: number;
    configured: boolean;
  } | null;
  registrationEnabled?: boolean;
  disabledLabel?: string;
  index?: number;
};

export function InstitutionSkillCard({
  competitionId,
  skillId,
  skillName,
  familyName,
  number,
  quota,
  registrationEnabled = true,
  disabledLabel = "Registration unavailable",
  index = 0,
}: InstitutionSkillCardProps) {
  const registerHref = `/institution/competitions/${competitionId}/register?skillId=${encodeURIComponent(skillId)}`;
  const hasQuotaSpace = !quota?.configured || quota.remaining > 0;
  const canRegister = registrationEnabled && hasQuotaSpace;

  return (
    <Card
      className={cn(
        "h-full border-border/80 shadow-sm",
        !canRegister && "opacity-80",
      )}
      data-testid="institution-skill-card"
      style={{ animationDelay: `${0.05 * index}s` }}
    >
      <CardHeader className="space-y-1 pb-2">
        {familyName ? (
          <p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">
            {familyName}
          </p>
        ) : null}
        <h3 className="font-semibold leading-snug">{skillName}</h3>
        <CardDescription>
          {[
            number ? `Skill ${number}` : null,
            quota?.configured
              ? `${quota.remaining} of ${quota.max} slots left`
              : quota
                ? "Quota not configured"
                : null,
          ]
            .filter(Boolean)
            .join(" · ")}
        </CardDescription>
      </CardHeader>
      <CardContent>
        {canRegister ? (
          <Button className="min-h-11 w-full gap-2" asChild>
            <Link
              href={registerHref}
              data-testid={`register-skill-${skillId}`}
            >
              <UserPlusIcon className="size-4" aria-hidden />
              Register
            </Link>
          </Button>
        ) : (
          <Button className="min-h-11 w-full" disabled>
            {registrationEnabled ? "Quota full" : disabledLabel}
          </Button>
        )}
        {quota?.configured ? (
          <span
            className="sr-only"
            data-testid={`quota-remaining-${skillId}`}
          >
            {quota.remaining}
          </span>
        ) : null}
      </CardContent>
    </Card>
  );
}
